 as v(kind text,exercise text,answers jsonb)
where c.title='ProfessionalEnglish_ThreeGardenRoad_HK'
on conflict(kind,exercise) do update
 set course_id=excluded.course_id,answers=excluded.answers;

-- l2d2 used to contain the beginner dialogue. Keep its original saved state and
-- copy compatible attempts to the explicit beginner ID, including the last-mode
-- pointer. Existing destination attempts and professional-version drafts win.
insert into public.special_learning_state(account_id,key,value,updated_at)
select s.account_id,
 'draft:l2d2-beginner:' || substr(s.key,length('draft:l2d2:')+1),
 s.value || '{"contentVersion":1}'::jsonb,
 s.updated_at
from public.special_learning_state s
where s.key like 'draft:l2d2:%'
 and jsonb_typeof(s.value)='object'
 and (not (s.value ? 'contentVersion') or s.value->'contentVersion'='1'::jsonb)
on conflict(account_id,key) do nothing;
